(async () => {
  try {
    const crawl = await window.TuquetCrawler.crawlDocument(document, { toMarkdown: true });
    automaNextBlock({
      stage: 1,
      url: window.location.href,
      status: 'ok',
      title: crawl.metadata?.title || document.title
    });
  } catch (e) {
    automaNextBlock({ stage: 1, error: e.message });
  }
})();

(async () => {
  try {
    const crawl = await window.TuquetCrawler.crawlDocument(document, { toMarkdown: true });
    automaNextBlock({
      stage: 2,
      url: window.location.href,
      pageType: crawl.pageType,
      status: 'handled_404'
    });
  } catch (e) {
    automaNextBlock({ stage: 2, error: e.message });
  }
})();

(async () => {
  try {
    const crawl = await window.TuquetCrawler.crawlDocument(document, { toMarkdown: true });
    automaNextBlock({
      stage: 3,
      url: window.location.href,
      status: 'delayed_success'
    });
  } catch (e) {
    automaNextBlock({ stage: 3, error: e.message });
  }
})();

(async () => {
  try {
    const crawl = await window.TuquetCrawler.crawlDocument(document, { toMarkdown: true });
    const quotes = document.querySelectorAll('.quote').length;
    automaNextBlock({
      stage: 4,
      url: window.location.href,
      status: 'spa_success',
      quotesCount: quotes
    });
  } catch (e) {
    automaNextBlock({ stage: 4, error: e.message });
  }
})();
